mapper.select:
SELECT ec.id, ec.class_id as classId, ec.class_name as className, ec.campus_name as campusName, ec.class_category as classCategory, ec.building FROM empty_classroom ec INNER JOIN classroom_availability ca ON ec.id = ca.classroom_id WHERE ec.week_number = #{week} AND ec.weekday = #{weekday} AND ca.empty_session IN
#{session}
GROUP BY ec.id HAVING COUNT(DISTINCT ca.empty_session) = #{size}
